$connectionString = 'Data Source=DESKTOP-PBMQQ03\SQLEXPRESS;Initial Catalog=W2023;User ID=THSTrong_Demo1;Password=2026.@#wb.nw.01'
$query = @"
Select Count(1) as TotalSeeded
From INFO_Information
Where IsDeleted = 0
	and Source = N'https://cdktcnqn.edu.vn/tin-tuc/hoat-dong-dang-bo/152';
Select Top 3
	Title,
	InformationLink,
	Convert(varchar(10), DisplayFromDate, 120) as DisplayFromDate
From INFO_Information
Where IsDeleted = 0
	and Source = N'https://cdktcnqn.edu.vn/tin-tuc/hoat-dong-dang-bo/152'
Order By DisplayFromDate Desc;
"@
Add-Type -AssemblyName System.Data
$connection = New-Object System.Data.SqlClient.SqlConnection($connectionString)
$command = $connection.CreateCommand()
$command.CommandText = $query
try {
    $connection.Open()
    $reader = $command.ExecuteReader()
    do {
        while ($reader.Read()) {
            $values = @()
            for ($i = 0; $i -lt $reader.FieldCount; $i++) { $values += ("{0}={1}" -f $reader.GetName($i), $reader.GetValue($i)) }
            Write-Output ($values -join ' | ')
        }
    } while ($reader.NextResult())
} finally {
    if ($reader) { $reader.Close() }
    if ($connection.State -ne 'Closed') { $connection.Close() }
}

$url = 'https://cdktcnqn.edu.vn/tin-tuc/hoat-dong-dang-bo/152'
try {
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    $response = Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec 30
    Write-Output ("Status={0}" -f $response.StatusCode)
    Write-Output ("Length={0}" -f $response.Content.Length)
    $matches = [regex]::Matches($response.Content, '<img[^>]+(?:src|data-src)=["'']([^"'']+)["''][^>]*>', 'IgnoreCase')
    Write-Output ("Images={0}" -f $matches.Count)
    $matches | Select-Object -First 40 | ForEach-Object { Write-Output $_.Groups[1].Value }
} catch {
    Write-Error $_.Exception.Message
    exit 1
}

