        [void]$command.Parameters.Add('@ThumbImage', [System.Data.SqlDbType]::NVarChar, 200)
        [void]$command.Parameters.Add('@InformationLink', [System.Data.SqlDbType]::VarChar, 500)
        $command.Parameters['@ThumbImage'].Value = [string]$item.LocalUrl
        $command.Parameters['@InformationLink'].Value = [string]$item.Slug
        [void]$command.ExecuteNonQuery()
    }
    $verify = $connection.CreateCommand()
    $verify.CommandText = "Select Count(1) From INFO_Information Where IsDeleted = 0 and Source = N'https://cdktcnqn.edu.vn/tin-tuc/hoat-dong-dang-bo/152' and Isnull(ThumbImage, N'') <> N''"
    $count = $verify.ExecuteScalar()
    Write-Output ("UpdatedThumbImages={0}" -f $count)
} finally {
    if ($connection.State -ne 'Closed') { $connection.Close() }
}

